{
  "block": "irq_ctrl",
  "spec": ["interface_spec.md"],
  "requirements": [
    {
      "id": "IRQ-PARAM",
      "source": "interface_spec.md",
      "text": "The block works for every `N` from 2 to 32, and bits `N` and up of the `ENABLE`, `MODE` and `PENDING` registers read as zero and ignore writes."
    },
    {
      "id": "IRQ-RESET",
      "source": "interface_spec.md",
      "text": "While `rst_n` is low at a rising edge of `clk`, `ENABLE`, `MODE` and `PENDING` clear to zero and the remembered level of every source clears to zero."
    },
    {
      "id": "IRQ-REG-RW",
      "source": "interface_spec.md",
      "text": "A write to `ENABLE` or `MODE` stores `wdata` bits `N-1` to 0 in that register."
    },
    {
      "id": "IRQ-READ",
      "source": "interface_spec.md",
      "text": "A read never changes any register; `rdata` follows `addr` with no clock edge."
    },
    {
      "id": "IRQ-LEVEL",
      "source": "interface_spec.md",
      "text": "A high-level source sets its `PENDING` bit at every rising edge where its input is high."
    },
    {
      "id": "IRQ-EDGE",
      "source": "interface_spec.md",
      "text": "A rising-edge source sets its `PENDING` bit at a rising edge where its input is high and was low at the previous rising edge, so an input held high sets it once."
    },
    {
      "id": "IRQ-DETECT-DISABLED",
      "source": "interface_spec.md",
      "text": "Detection does not depend on `ENABLE`: a disabled source still sets its `PENDING` bit."
    },
    {
      "id": "IRQ-W1C",
      "source": "interface_spec.md",
      "text": "A write to `PENDING` clears each bit written 1 and leaves each bit written 0 unchanged; it never sets a bit."
    },
    {
      "id": "IRQ-ACK",
      "source": "interface_spec.md",
      "text": "A write to `CLAIM` acknowledges the source whose number is in `wdata` bits 4 to 0: that source's `PENDING` bit clears and no other bit changes; a number of `N` or more changes nothing."
    },
    {
      "id": "IRQ-SET-WINS",
      "source": "interface_spec.md",
      "text": "A source detected at the same rising edge as a write that clears its bit keeps its `PENDING` bit set, so a high-level source acknowledged while its input is still high stays pending."
    },
    {
      "id": "IRQ-MASK",
      "source": "interface_spec.md",
      "text": "`irq` is high exactly when some source has both its `PENDING` and its `ENABLE` bit set, for high-level and rising-edge sources alike."
    },
    {
      "id": "IRQ-PRIORITY",
      "source": "interface_spec.md",
      "text": "`irq_id` is the lowest-numbered source whose `PENDING` and `ENABLE` bits are both set, so source 0 has the highest priority, and it is 0 while `irq` is low."
    },
    {
      "id": "IRQ-CLAIM",
      "source": "interface_spec.md",
      "text": "A read of `CLAIM` returns `irq` in bit 31 and `irq_id` in bits 4 to 0, with every other bit zero."
    },
    {
      "id": "IRQ-LATENCY",
      "source": "interface_spec.md",
      "text": "`irq` and `irq_id` follow the registers with no clock edge, so a source detected at one rising edge drives `irq` until the next."
    }
  ],
  "items": [
    {
      "name": "test_reset_smoke",
      "kind": "test",
      "file": "tb_irq_ctrl.sv",
      "proves": ["IRQ-RESET"],
      "description": "Goal: reset clears ENABLE, MODE, PENDING and the remembered source levels. Stimulus: load nonzero ENABLE, MODE and PENDING; hold some edge-mode sources high; assert rst_n low for one or more rising edges; release reset with those sources still high. Check: all three registers read 0 after reset. An edge-mode source held high through reset sets PENDING at the first edge after reset, which shows its remembered level was 0. irq is low and irq_id is 0."
    },
    {
      "name": "test_reg_rw",
      "kind": "test",
      "file": "tb_irq_ctrl.sv",
      "proves": ["IRQ-REG-RW", "IRQ-READ"],
      "description": "Goal: ENABLE and MODE store wdata bits N-1 to 0, and reads have no side effects. Stimulus: write walking-ones, walking-zeros and random patterns to addr 0 and 1; read every addr repeatedly with we low. Check: readback equals wdata masked to N bits. Reading any register, including PENDING and CLAIM, leaves all registers and irq unchanged."
    },
    {
      "name": "test_param_sweep",
      "kind": "test",
      "file": "tb_irq_ctrl.sv",
      "proves": ["IRQ-PARAM"],
      "description": "Goal: correct behaviour across N, and upper bits read as zero. Stimulus: build and run at N in {2, 8, 31, 32}; write all-ones to ENABLE, MODE and PENDING; drive every source. Check: bits N and up of ENABLE, MODE and PENDING read 0, and writes to those bits have no effect. The detection, clear and claim checks from the other tests also hold at each N."
    },
    {
      "name": "test_level_detect",
      "kind": "test",
      "file": "tb_irq_ctrl.sv",
      "proves": ["IRQ-LEVEL", "IRQ-DETECT-DISABLED"],
      "description": "Goal: high-level sources set PENDING at every edge where the input is high, whether or not they are enabled. Stimulus: MODE=0; hold a source high; clear PENDING with W1C while it stays high; repeat with ENABLE both set and cleared for that source. Check: PENDING is set at the next edge after each clear while the input stays high. A disabled source sets PENDING but does not raise irq."
    },
    {
      "name": "test_edge_detect",
      "kind": "test",
      "file": "tb_irq_ctrl.sv",
      "proves": ["IRQ-EDGE", "IRQ-DETECT-DISABLED"],
      "description": "Goal: rising-edge sources set PENDING once per low-to-high transition, whether or not they are enabled. Stimulus: MODE=1; pulse a source for one cycle; hold a source high for many cycles and clear PENDING partway through; toggle a source; repeat with ENABLE both set and cleared. Check: PENDING is set exactly at the edge where the input goes from low to high. It is not set again while the input stays high after a clear. A disabled source still sets PENDING."
    },
    {
      "name": "test_pending_w1c",
      "kind": "test",
      "file": "tb_irq_ctrl.sv",
      "proves": ["IRQ-W1C"],
      "description": "Goal: writing PENDING clears bits written 1, keeps bits written 0, and never sets a bit. Stimulus: build up a known PENDING pattern with all sources then idle; write random masks to addr 2, including ones in positions whose PENDING bit is 0. Check: new PENDING equals old PENDING AND NOT wdata. No bit goes from 0 to 1 because of the write."
    },
    {
      "name": "test_claim_ack",
      "kind": "test",
      "file": "tb_irq_ctrl.sv",
      "proves": ["IRQ-ACK", "IRQ-CLAIM"],
      "description": "Goal: CLAIM reads report irq and irq_id, and CLAIM writes acknowledge exactly one source. Stimulus: set several pending, enabled sources; read addr 3; write their indices to addr 3 one at a time; write indices N to 31 and values with junk in bits 31 to 5. Check: the CLAIM read has irq in bit 31, irq_id in bits 4 to 0, and zeros elsewhere. A write clears only the PENDING bit named by wdata bits 4 to 0. An index of N or more changes nothing."
    },
    {
      "name": "test_set_wins",
      "kind": "test",
      "file": "tb_irq_ctrl.sv",
      "proves": ["IRQ-SET-WINS"],
      "description": "Goal: a detection at the same edge as a clear wins. Stimulus: at one edge, detect a source (a level source held high, or an edge source going low to high) while also writing PENDING with that bit set, and separately while writing CLAIM with that index. Check: the PENDING bit stays set after the edge in both cases. A high-level source acknowledged while still high stays pending."
    },
    {
      "name": "test_mask_priority",
      "kind": "test",
      "file": "tb_irq_ctrl.sv",
      "proves": ["IRQ-MASK", "IRQ-PRIORITY"],
      "description": "Goal: irq and irq_id reflect PENDING AND ENABLE with lowest-index priority. Stimulus: random PENDING and ENABLE combinations over mixed MODE settings, including the empty case, a single source, all sources, and source 0 together with source N-1. Check against a reference model on every cycle: irq equals the OR of (PENDING AND ENABLE). irq_id is the lowest set index, and 0 when irq is low."
    },
    {
      "name": "test_latency",
      "kind": "test",
      "file": "tb_irq_ctrl.sv",
      "proves": ["IRQ-LATENCY", "IRQ-READ"],
      "description": "Goal: irq, irq_id and rdata are combinational from the registers and addr. Stimulus: detect an enabled source at an edge; change ENABLE with a write; change addr between edges. Check: irq and irq_id change in the same cycle the register changes, with no extra edge. irq stays high until the edge where the pending bit is cleared. rdata changes with addr between clock edges."
    },
    {
      "name": "a_irq_mask",
      "kind": "assertion",
      "file": "irq_ctrl_sva.sv",
      "proves": ["IRQ-MASK"],
      "description": "Concurrent assertion, checked at all times: irq == |(PENDING & ENABLE)."
    },
    {
      "name": "a_irq_id_priority",
      "kind": "assertion",
      "file": "irq_ctrl_sva.sv",
      "proves": ["IRQ-PRIORITY"],
      "description": "Assertion: irq_id equals the index of the lowest set bit of (PENDING & ENABLE), and irq_id == 0 when irq is low."
    },
    {
      "name": "a_claim_format",
      "kind": "assertion",
      "file": "irq_ctrl_sva.sv",
      "proves": ["IRQ-CLAIM"],
      "description": "Assertion: when addr == 3, rdata == {irq, 26'b0, irq_id}."
    },
    {
      "name": "a_upper_bits_zero",
      "kind": "assertion",
      "file": "irq_ctrl_sva.sv",
      "proves": ["IRQ-PARAM"],
      "description": "Assertion: when addr is 0, 1 or 2, rdata bits 31 to N are zero, for every N in the sweep."
    },
    {
      "name": "a_pending_next",
      "kind": "assertion",
      "file": "irq_ctrl_sva.sv",
      "proves": ["IRQ-W1C", "IRQ-ACK", "IRQ-LEVEL", "IRQ-EDGE", "IRQ-DETECT-DISABLED"],
      "description": "Next-state assertion for PENDING out of reset. Next PENDING = (PENDING AND NOT clear_mask) OR detect. clear_mask is wdata on a PENDING write, the one-hot index on a CLAIM write with index below N, and 0 otherwise. detect is src for level-mode bits and src AND NOT the previous src for edge-mode bits, and does not depend on ENABLE."
    },
    {
      "name": "a_set_wins",
      "kind": "assertion",
      "file": "irq_ctrl_sva.sv",
      "proves": ["IRQ-SET-WINS"],
      "description": "Assertion: if a source is detected at an edge where a PENDING or CLAIM write clears its bit, its PENDING bit is 1 after that edge."
    },
    {
      "name": "a_reset_clears",
      "kind": "assertion",
      "file": "irq_ctrl_sva.sv",
      "proves": ["IRQ-RESET"],
      "description": "Assertion: rst_n low at a rising edge implies ENABLE, MODE, PENDING and the remembered source levels are 0 after that edge."
    }
  ]
}
